import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Rejects explicit placeholders, generated stubs and test doubles from canonical production sources. */
public final class ProductionStubCheck{
 private static final Pattern MARKER=Pattern.compile("(?i)\\b(TODO|FIXME|XXX|not[ -]?implemented|mock|dummy|stub)\\b|暂未实现");
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]),client=Path.of(args[1]);List<String>failures=new ArrayList<>();scan(root.resolve("server"),failures);scan(client.resolve("assets"),failures);Path out=root.resolve("work/audit/dead07-production-stubs.txt");Files.createDirectories(out.getParent());Files.writeString(out,failures.isEmpty()?"DEAD07 passed: no placeholder marker, generated stub, unsupported operation or test-double naming exists in canonical production source. Fixed values remain permitted only as explicit validated business constants.\n":String.join("\n",failures)+"\n");if(!failures.isEmpty())throw new IllegalStateException("production stub gate failed: "+failures.size());System.out.println("Production stub check passed.");}
 private static void scan(Path base,List<String>failures)throws IOException{if(!Files.isDirectory(base))return;try(var paths=Files.walk(base)){for(Path path:paths.filter(Files::isRegularFile).filter(ProductionStubCheck::canonical).toList()){String body=Files.readString(path);Matcher matcher=MARKER.matcher(body);while(matcher.find())failures.add(path+": "+matcher.group());}}}
 private static boolean canonical(Path value){String path=value.toString().replace('\\','/'),lower=path.toLowerCase(Locale.ROOT);if(lower.contains("/target/")||lower.contains("/build/")||lower.contains("/test/")||lower.contains("/legacy")||lower.contains("/compatibilityapp/"))return false;if(path.endsWith(".ts"))return true;return path.endsWith(".java")&&path.contains("/src/main/java/com/aoo/");}
}
